/* generated child CSS: blocks/15-blog/blog.index-dynamic/block.css */
.blog-index {
  position: relative;
  overflow: hidden;
  padding: clamp(7rem, 11vw, 11rem) 0 clamp(5rem, 9vw, 9rem);
  color: var(--color-text);
  background:
    radial-gradient(circle at 82% 8%, rgba(107, 234, 249, 0.2), transparent 30rem),
    var(--color-bg);
}

.blog-index::before {
  content: "";
  position: absolute;
  width: 28rem;
  aspect-ratio: 1;
  left: -17rem;
  top: 20rem;
  border: 1px solid rgba(92, 100, 116, 0.13);
  border-radius: 50%;
  pointer-events: none;
}

.blog-index__container { position: relative; }
.blog-index__hero { max-width: 79rem; }
.blog-index__eyebrow,
.blog-card__category {
  color: var(--color-text-accent, #2499a8);
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.blog-index__title {
  max-width: 68rem;
  margin: 1rem 0 0;
  font-size: clamp(3rem, 7vw, 7.5rem);
  line-height: 0.94;
  letter-spacing: -0.06em;
}

.blog-index__intro {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(17rem, 0.75fr);
  gap: clamp(2rem, 8vw, 9rem);
  margin-top: clamp(3rem, 7vw, 6rem);
  padding-top: 2rem;
  border-top: 1px solid rgba(92, 100, 116, 0.2);
}

.blog-index__intro h2,
.blog-index__intro h3 { margin: 0; color: var(--color-heading); }
.blog-index__intro h2 { font-size: clamp(1.8rem, 3.5vw, 3.6rem); line-height: 1.05; }
.blog-index__intro h3 { font-size: clamp(1.3rem, 2vw, 2rem); line-height: 1.15; }
.blog-index__intro p { max-width: 47rem; margin: 1rem 0 0; font-size: clamp(1rem, 1.4vw, 1.2rem); line-height: 1.65; }

.blog-index__status { margin: 4rem 0 0; color: var(--color-gray-blue); }
.blog-index__featured { margin-top: clamp(4rem, 8vw, 8rem); }
.blog-featured__link {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(20rem, 0.85fr);
  min-height: 34rem;
  overflow: hidden;
  border: 1px solid rgba(92, 100, 116, 0.16);
  border-radius: clamp(1.5rem, 3vw, 3.25rem);
  background: color-mix(in srgb, var(--color-gray-bg) 92%, transparent);
  color: inherit;
  text-decoration: none;
  box-shadow: 0 1.5rem 5rem rgba(23, 23, 27, 0.06);
}

.blog-card__media { position: relative; display: block; overflow: hidden; background: linear-gradient(135deg, #17171b 0%, #273240 55%, #6beaf9 170%); }
.blog-card__media::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 20% 20%, rgba(107, 234, 249, 0.4), transparent 35%); }
.blog-card__media img { width: 100%; height: 100%; object-fit: cover; transition: transform 500ms ease; }
.blog-featured__link:hover img,
.blog-card__link:hover img { transform: scale(1.035); }
.blog-featured__body { display: flex; flex-direction: column; justify-content: center; padding: clamp(2rem, 5vw, 5rem); }
.blog-card__meta { display: flex; align-items: center; flex-wrap: wrap; gap: 0.6rem 1rem; color: var(--color-gray-blue); font-size: 0.85rem; }
.blog-card__date::before,
.blog-card__read-time::before { content: ""; display: inline-block; width: 0.22rem; aspect-ratio: 1; margin: 0 0.65rem 0.2rem 0; border-radius: 50%; background: currentColor; }
.blog-featured__title { margin: 1.4rem 0 0; color: var(--color-heading); font-size: clamp(2.2rem, 4vw, 4.4rem); line-height: 0.98; letter-spacing: -0.045em; }
.blog-featured__summary { margin: 1.4rem 0 0; font-size: 1.1rem; line-height: 1.6; }
.blog-featured__author { margin-top: 1.5rem; color: var(--color-heading); font-size: 0.9rem; font-weight: 600; }
.blog-card__read { display: inline-flex; align-items: center; gap: 0.7rem; align-self: flex-start; margin-top: 2rem; color: var(--color-heading); font-weight: 650; }
.blog-card__read::after { content: "→"; color: var(--color-text-accent, #2499a8); transition: transform 180ms ease; }
a:hover .blog-card__read::after { transform: translateX(0.3rem); }

.blog-index__grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.25rem; margin-top: 1.25rem; }
.blog-card { min-width: 0; }
.blog-card__link { display: flex; min-height: 100%; flex-direction: column; overflow: hidden; border: 1px solid rgba(92, 100, 116, 0.15); border-radius: 2rem; background: var(--color-gray-bg); color: inherit; text-decoration: none; transition: transform 180ms ease, box-shadow 180ms ease; }
.blog-card__link:hover { transform: translateY(-0.35rem); box-shadow: 0 1.25rem 3.5rem rgba(23, 23, 27, 0.08); }
.blog-card__media--card { aspect-ratio: 16 / 10; }
.blog-card__body { display: flex; flex: 1; flex-direction: column; padding: 1.6rem; }
.blog-card__title { margin: 1rem 0 0; color: var(--color-heading); font-size: clamp(1.45rem, 2vw, 2rem); line-height: 1.12; letter-spacing: -0.03em; }
.blog-card__summary { margin: 1rem 0 0; line-height: 1.55; }
.blog-card__body .blog-card__read { margin-top: auto; padding-top: 1.75rem; }
.blog-index__actions { display: flex; justify-content: center; margin-top: 3rem; }
.blog-index__more { position: relative; min-width: 13rem; padding: 1rem 1.75rem; border: 1px solid rgba(92, 100, 116, 0.35); border-radius: 999px; background: transparent; color: var(--color-heading); cursor: pointer; font: inherit; font-weight: 650; }
.blog-index__more:hover { border-color: var(--color-text-accent, #2499a8); }

@media (max-width: 64rem) {
  .blog-featured__link { grid-template-columns: 1fr; min-height: 0; }
  .blog-card__media--featured { min-height: 25rem; }
  .blog-index__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 48rem) {
  .blog-index { padding-top: 6rem; }
  .blog-index__intro { grid-template-columns: 1fr; gap: 2.5rem; }
  .blog-index__grid { grid-template-columns: 1fr; }
  .blog-card__media--featured { min-height: 16rem; }
  .blog-featured__body { padding: 1.5rem; }
  .blog-featured__link,
  .blog-card__link { border-radius: 1.4rem; }
}

